// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, uint256 sendValue, address sender, bytes calldata data) public {
        vm.assume(sender != address(0) && sender != address(this) && sender != address(c));
        vm.assume(amount > 0);
        vm.assume(sendValue < 1 ether);
        bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);
        vm.assume(sendValue <= amount);
        vm.startPrank(c.owner());
        try c.sendMoney(address(0), sendValue, data) {} catch {}
        vm.stopPrank();
        uint balBefore = address(c).balance;
        vm.prank(sender);
        try c.withdraw(amount) {} catch {}
        assertTrue(address(c).balance == balBefore);
    }
}
